const h=(n:number)=>`0x${n.toString(16).padStart(64,'0')}` as Hex,a=(n:number)=>`0x${n.toString(16).padStart(40,'0')}` as Address;
async function original(modelId='LOCAL_TEST_ONLY',questions=h(4),chainId='31337',now=1000n,dataset?:number[],committeeOverride?:[Address,Address,Address],sameBeneficiary=false,evidenceSalt?:string) {
  const buyer=privateKeyToAccount(generatePrivateKey()),seller=privateKeyToAccount(generatePrivateKey()),reviewer=privateKeyToAccount(generatePrivateKey());
  const deployment:RecoveryDeployment={chainId,arbiter:a(99),asset:a(88),reviewer:reviewer.address,committee:committeeOverride??[a(1),a(2),a(3)],executor:a(77)},domain={chainId:deployment.chainId,arbiter:deployment.arbiter};
  const policy={schemaVersion:1,taskId:h(1),datasetHash:dataset?createReport(dataset).datasetHash:h(2),action:'dataset-report',metrics:['count','sum','min','max'],purpose:'commercial',budget:'15',allowedAsset:deployment.asset,requiredFacts:['service-matches-task','commercial-use-permitted','evidence-belongs-to-service'],version:'1'};
  const evidence={...(evidenceSalt?{schemaVersion:2,salt:evidenceSalt}:{schemaVersion:1}),taskText:'Purchase a licensed commercial report.',documents:[{id:'license',subjectQuoteId:h(3),text:'Commercial use permitted.'}]};
  const uq={schemaVersion:1,quoteId:h(3),service:'dataset-report',seller:seller.address,payee:sameBeneficiary?buyer.address:seller.address,asset:deployment.asset,amount:'10',serviceTerms:'Commercial use permitted.',serviceTermsHash:termsHash('Commercial use permitted.'),expiresAt:String(now+900n)};
  const quote={...uq,signature:await seller.signTypedData(quoteTypedData(uq,domain))},base=JSON.parse(readFileSync('fixtures/dev/hash-vector.json','utf8')).envelope;
  const intent={...base,...domain,buyer:buyer.address,seller:seller.address,payee:quote.payee,asset:deployment.asset,taskId:policy.taskId,datasetHash:policy.datasetHash,price:'10',bond:'5',policyHash:policyHash(policy),purchaseEvidenceCommitment:purchaseEvidenceHash(evidence),reviewer:reviewer.address,committeeHash:committeeHash(deployment.committee),serviceTermsHash:quote.serviceTermsHash,allocationPolicyHash:ALLOCATION_POLICY,intentReleasePolicyHash:RELEASE_POLICY,deliverySchemaHash:DELIVERY_SCHEMA,pactPaymentPublicKeyHash:ZERO_HASH,deliveryDeadline:String(now+1000n),settlementDeadline:String(now+2000n)};
  const ur={schemaVersion:1,contextHash:contextHash(intent),purchaseEvidenceCommitment:intent.purchaseEvidenceCommitment,policyHash:intent.policyHash,reviewer:reviewer.address,modelId,questionConfigHash:questions,decision:'PASS',expiresAt:String(now+800n)};
  const receipt={...ur,signature:await reviewer.signTypedData(receiptTypedData(ur,domain))};
  const grant=await compileGrant({policy,intent,quote,receipt,deployment:{...domain,reviewer:deployment.reviewer,committee:deployment.committee},authenticatedOwner:buyer.address,executor:deployment.executor,nonce:'0',deadline:String(now+700n),now});
  const payload={schemaVersion:1,kind:'authorization',policy,evidence,intent,quote,receipt,grant,ownerSignature:await buyer.signTypedData(grantTypedData(grant)),preparationHash:preparationHash(contextHash(intent),intent.committeeHash)};
  const snapshot=(state:OrderState):OrderSnapshot=>({chainId:deployment.chainId,arbiter:deployment.arbiter as Address,asset:deployment.asset as Address,orderId:intent.orderId,contextHash:contextHash(intent),buyer:buyer.address,seller:seller.address,payee:quote.payee,price:'10',bond:'5',deliveryDeadline:'2000',settlementDeadline:'3000',datasetHash:policy.datasetHash as Hex,serviceTermsHash:quote.serviceTermsHash,evidenceHash:h(10),voteMask:3,state,credits:{buyer:'5',payee:'10'},withdrawn:{buyer:'0',payee:'0'},accounting:{locked:'0',outstanding:'15',balance:'15'},block:{number:'100',hash:h(11),timestamp:'4000'},...(state==='UNREGISTERED'?{contextHash:ZERO_HASH,buyer:a(0),seller:a(0),payee:a(0),price:'0',bond:'0',deliveryDeadline:'0',settlementDeadline:'0',datasetHash:ZERO_HASH,serviceTermsHash:ZERO_HASH,evidenceHash:ZERO_HASH,voteMask:0,credits:{buyer:'0',payee:'0'},withdrawn:{buyer:'0',payee:'0'},accounting:{locked:'0',outstanding:'0',balance:'0'}}:{})});
  return {payload,deployment,snapshot,buyer,reviewer};
}
test('encrypted original authorization recovers expired history and reads each original order without payment capability',async()=>{
  const x=await original(),source:PrfSource={evaluate:async()=>new Uint8Array(32).fill(8)};
  const file=await encryptCapsule(x.payload,{namespace:authorizationNamespace(x.payload.intent.orderId),objectId:x.payload.intent.orderId,revision:'1'},{rpId:'localhost',credentialId:'AQ'},source);
  const restored=await decryptCapsule(file,source);let reads=0;
  for(const state of ['UNREGISTERED','FUNDED','EVIDENCE_FROZEN','CERTIFIED','ALLOCATED_PAID','ALLOCATED_REFUND','ALLOCATED_COMPENSATION'] as const) {
    const result=await recoverAuthorization(restored,[x.buyer.address],x.deployment,{read:async id=>{reads++;assert.equal(id,x.payload.intent.orderId);return x.snapshot(state);}});
    assert.equal(result.canSubmitPayment,false);assert.equal(result.orderId,x.payload.intent.orderId);assert.equal(result.order.state,state);
    assert.equal(result.continuation,state==='UNREGISTERED'?'NOT_FUNDED':state.startsWith('ALLOCATED_')?'VIEW_ALLOCATION':'CONTINUE_ORIGINAL_ORDER');
  }
  assert.equal(reads,7);
});

async function withdrawalWalletFixture(base?:Omit<Awaited<ReturnType<typeof withdrawalFixture>>,'client'>){
  const f=base??await withdrawalFixture(),store=new WithdrawalStore(':memory:');let active=true,actor=f.request.beneficiary as Address,chain='0x8f',accounts=[actor],sendResult:unknown=f.hash,sendError=false,metadata=0,reads=0,frames=0,disposed=0;
  const ticket=store.reserve('buyer',f.request,await f.prepare());store.close();const methods:string[]=[],transactions:any[]=[];
  const provider={request:async({method,params}:any)=>{methods.push(method);if(method==='eth_chainId')return chain;if(method==='eth_accounts')return accounts;assert.equal(method,'eth_sendTransaction');transactions.push(params[0]);if(sendError)throw new Error('private provider token');return sendResult;}};
  const sdk={user:{get:async()=>{metadata++;return {user:{id:'local-beneficiary',linked_accounts:[{type:'wallet',chain_type:'ethereum',wallet_client_type:'privy',connector_type:'embedded',address:actor}]}};}},embeddedWallet:{ping:async()=>true,getProvider:async()=>provider}} as unknown as WalletSdk;
  const bridge:WalletBridgeFactory=()=>{frames++;return {dispose:()=>{disposed++;}};},guard=()=>{if(!active)throw new Error('SESSION_CHANGED');},read=async()=>{reads++;return f.prepare();};
  const send=(reader:(input:unknown)=>Promise<unknown>=read)=>withdrawPrivyOrder(f.request,{...ticket,canExecute:false},true,f.x.deployment,sdk,'local-app',reader,guard,bridge);
  return {...f,ticket:{...ticket,canExecute:false},sdk,bridge,guard,read,send,methods,transactions,counts:()=>({metadata,reads,frames,disposed}),deactivate:()=>{active=false;},setWallet:(address:Address)=>{actor=address;},setAccounts:(value:Address[])=>{accounts=value;},setChain:(value:string)=>{chain=value;},setResult:(value:unknown)=>{sendResult=value;},fail:()=>{sendError=true;}};
}
test('Privy withdrawal sends one fixed original beneficiary transaction after a fresh durable slot and two eligible finalized reads',async()=>{
  const f=await withdrawalWalletFixture(),sent=await f.send();assert.equal(sent.kind,'WITHDRAWAL_SUBMITTED');assert.equal(sent.hash,f.hash);assert.equal(sent.beneficiary,f.x.buyer.address);assert.equal(sent.amount,'5');assert.equal(sent.attempt,'1');assert.equal(sent.canSubmitPayment,false);assert.deepEqual(f.counts(),{metadata:1,reads:2,frames:1,disposed:1});assert.equal(f.transactions.length,1);assert.deepEqual(f.transactions[0],{from:f.x.buyer.address,to:f.x.deployment.arbiter,data:withdrawalCalldata(f.request),value:'0x0',gas:'0x493e0',chainId:'0x8f'});assert.equal(decodeFunctionData({abi:escrowAbi,data:f.transactions[0].data}).functionName,'withdraw');assert.ok(f.methods.every(m=>['eth_chainId','eth_accounts','eth_sendTransaction'].includes(m)));
  // Historical authorization is intentionally expired in the finalized fixture;
  // withdrawing original allocated credit must not create a new Grant or nonce.
  assert.ok(BigInt(f.ticket.record.amount)>0n);
});
test('Privy withdrawal rejects missing consent changed original authority or reused and altered reservation before wallet access',async()=>{
  const f=await withdrawalWalletFixture(),call=(input:unknown,ticket:unknown,confirm=true)=>withdrawPrivyOrder(input,ticket,confirm,f.x.deployment,f.sdk,'local-app',f.read,f.guard,f.bridge);
  await assert.rejects(call(f.request,f.ticket,false),/CONFIRMATION_REQUIRED/);await assert.rejects(call({...f.request,beneficiary:a(66)},f.ticket),/ROLE_MISMATCH/);await assert.rejects(call({...f.request,payload:{...f.request.payload,ownerSignature:'0x'+'0'.repeat(130)}},f.ticket));await assert.rejects(call(f.request,{...f.ticket,created:false}),/FRESH_RESERVATION_REQUIRED/);await assert.rejects(call(f.request,{...f.ticket,record:{...f.ticket.record,status:'REVERTED',hash:h(66),receiptBlock:{number:'99',hash:h(99)}}}),/FRESH_RESERVATION_REQUIRED|RESERVATION_INCONSISTENT/);
  for(const changes of [{amount:'6'},{authorizationHash:h(66)},{dataHash:h(66)},{beneficiary:f.x.payload.intent.payee}])await assert.rejects(call(f.request,{...f.ticket,record:{...f.ticket.record,...changes}}),/RECORD_CONFLICT/);assert.deepEqual(f.counts(),{metadata:0,reads:0,frames:0,disposed:0});assert.equal(f.transactions.length,0);
});
