  f.setAllowance(0n);const changed=await f.read();assert.equal(changed.status,'CONFIRMED');assert.ok('exactAllowance'in changed&&!changed.exactAllowance);assert.ok('approvedAmount'in changed&&changed.approvedAmount==='15');
  const reverted=await approvalReceiptFixture();reverted.receipt.status='reverted';reverted.receipt.logs=[];reverted.setAllowance(0n);assert.equal((await reverted.read()).status,'REVERTED');
