  for(const mutate of [(v:Awaited<ReturnType<typeof approvalReceiptFixture>>)=>{v.transaction.to=a(55);},(v:Awaited<ReturnType<typeof approvalReceiptFixture>>)=>{v.receipt.logs=[];},(v:Awaited<ReturnType<typeof approvalReceiptFixture>>)=>{v.reorg();}]){const g=await approvalReceiptFixture();mutate(g);await assert.rejects(g.read(),/MISMATCH|UNPROVEN|CHANGED/);}
