function withdrawalDom(){const nodes=new Map<string,any>();for(const match of withdrawalControls.matchAll(/id="([^"]+)"/g)){const handlers=new Map<string,(()=>void)[]>(),node={isConnected:true,disabled:/^(refresh-withdrawal|send-withdrawal|reconcile-withdrawal|retry-withdrawal)$/.test(match[1]),checked:false,hidden:match[1]==='withdrawal-preview',textContent:'',value:match[1]==='withdrawal-role'?'buyer':'',files:[] as unknown[],addEventListener:(event:string,callback:()=>void)=>{handlers.set(event,[...(handlers.get(event)??[]),callback]);},emit:(event:string)=>{if(event==='click'&&node.disabled)throw new Error('DOM_BUTTON_DISABLED');for(const callback of handlers.get(event)??[])callback();}};nodes.set(match[1],node);}return {nodes,document:{querySelector:(selector:string)=>nodes.get(selector.slice(1))},detach:()=>{for(const node of nodes.values())node.isConnected=false;}};}
