  const transfer=await allocationFixture(),abi=[{type:'event',name:'Transfer',inputs:[{name:'from',type:'address',indexed:true},{name:'to',type:'address',indexed:true},{name:'value',type:'uint256',indexed:false}]}] as const;transfer.receipt.logs.push({address:transfer.x.deployment.asset,removed:false,data:encodeAbiParameters([{type:'uint256'}],[10n]),topics:encodeEventTopics({abi,eventName:'Transfer',args:{from:transfer.x.deployment.arbiter as Address,to:transfer.x.payload.intent.payee}})});await assert.rejects(transfer.proof(),/EFFECT_UNPROVEN/);
