test('allocation pending and reverted receipts never claim new credits while DTO validation rejects substituted amounts actors and calls',async()=>{
  const f=await allocationFixture();f.setFinal(99n);assert.equal((await f.proof()).status,'PENDING');const missing=await allocationFixture();missing.missing();assert.equal((await missing.proof()).status,'PENDING');const failed=await allocationFixture();failed.receipt.status='reverted';failed.receipt.logs=[];const proof=await failed.proof();assert.ok(proof.status==='REVERTED'&&proof.buyerAmount==='0'&&proof.payeeAmount==='0');assert.throws(()=>checkAllocationReceipt({...failed.request,action:failed.action,hash:failed.hash},{...proof,buyerAmount:'5'}),/EFFECT_UNPROVEN/);
  const o=f.order();f.setOrder({...o,state:'CERTIFIED',credits:{buyer:'0',payee:'0'},accounting:{locked:'15',outstanding:'0',balance:'15'}});const p=await f.prepare();for(const changed of [{data:'0x1234'},{executor:f.x.buyer.address},{buyerAmount:'15'},{gates:[{...p.gates[0],eligible:null},p.gates[1]]},{finality:'latest'}])assert.throws(()=>checkAllocationPreparation(f.request,{...p,...changed}));
});
